#!/usr/bin/env node
// Rebuild every generated file from data/products.mjs.
// Run: node build/build.mjs
//
// Outputs:
//   assets/products-data.js  (browser copy of the product data)
//   p/<slug>.html            (one page per product)
//   sitemap.xml              (site map with every URL)

import { writeFileSync, mkdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { AFFILIATE_TAG, categories, products, productsBySlug, amazonUrl, reviewsUrl } from '../data/products.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, '..');
const SITE_URL = 'https://smart-kitchen-7br.pages.dev';

// ---------- 1. Browser copy of the data ---------------------------------
const browserData =
`// AUTO-GENERATED by build/build.mjs from data/products.mjs. Do not edit by hand.
window.SK_DATA = ${JSON.stringify({
  affiliateTag: AFFILIATE_TAG,
  categories,
  products
}, null, 2)};
`;
writeFileSync(join(root, 'assets/products-data.js'), browserData);

// ---------- 2. Per-product pages ----------------------------------------
mkdirSync(join(root, 'p'), { recursive: true });

const escapeHtml = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const imgFor = p => p.image ? `assets/${encodeURI(p.image)}` : '';

function relatedFor(product){
  return products.filter(p => p.category === product.category && p.slug !== product.slug).slice(0, 3);
}

function productPage(p){
  const canonical = `${SITE_URL}/p/${p.slug}.html`;
  const cat = categories.find(c => c.id === p.category);
  const buyUrl = amazonUrl(p);
  const revUrl = reviewsUrl(p);
  const priceRange = { '$': [10, 25], '$$': [25, 60], '$$$': [60, 150] }[p.priceHint] || [15, 50];
  const jsonLd = {
    '@context':'https://schema.org',
    '@type':'Product',
    'name': p.name,
    'description': p.longDesc,
    'category': cat?.title || 'Kitchen',
    'image': `${SITE_URL}/${imgFor(p)}`,
    'brand': { '@type':'Brand', 'name':'Various' },
    'offers': {
      '@type':'AggregateOffer',
      'availability':'https://schema.org/InStock',
      'url': buyUrl,
      'priceCurrency':'USD',
      'lowPrice': priceRange[0],
      'highPrice': priceRange[1],
      'offerCount': 1
    }
  };
  const faqLd = p.faqs?.length ? {
    '@context':'https://schema.org',
    '@type':'FAQPage',
    'mainEntity': p.faqs.map(f => ({
      '@type':'Question',
      'name': f.q,
      'acceptedAnswer': { '@type':'Answer', 'text': f.a }
    }))
  } : null;
  const breadcrumbLd = {
    '@context':'https://schema.org',
    '@type':'BreadcrumbList',
    'itemListElement':[
      {'@type':'ListItem','position':1,'name':'Home','item':`${SITE_URL}/`},
      {'@type':'ListItem','position':2,'name':'All products','item':`${SITE_URL}/products.html`},
      {'@type':'ListItem','position':3,'name':p.name,'item':canonical}
    ]
  };
  const related = relatedFor(p);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(p.name)}: Buying Guide & Tips | Smart Kitchen</title>
<meta name="description" content="${escapeHtml(p.shortDesc)} What to look for, common questions, and where to compare on Amazon.">
<link rel="canonical" href="${canonical}">
<meta property="og:title" content="${escapeHtml(p.name)} | Smart Kitchen">
<meta property="og:description" content="${escapeHtml(p.shortDesc)}">
<meta property="og:type" content="article">
<meta property="og:image" content="${SITE_URL}/${imgFor(p)}">
<meta name="twitter:card" content="summary_large_image">
<link rel="stylesheet" href="../assets/styles.css">
<link rel="stylesheet" href="../assets/kitchen.css">
<link rel="stylesheet" href="../assets/product-page.css">
<script defer src="../assets/products-data.js"></script>
<script defer src="../assets/site.js"></script>
<script type="application/ld+json">${JSON.stringify(jsonLd)}</script>
${faqLd ? `<script type="application/ld+json">${JSON.stringify(faqLd)}</script>` : ''}
<script type="application/ld+json">${JSON.stringify(breadcrumbLd)}</script>
</head>
<body>
<a class="skip" href="#main">Skip to content</a>
<div data-site-header></div>
<main id="main" class="section product-page">
  <div class="container">
    <nav class="breadcrumb" aria-label="Breadcrumb">
      <a href="../index.html">Home</a> &rsaquo; <a href="../products.html">All products</a> &rsaquo;
      <a href="../index.html#${p.category}">${escapeHtml(cat?.title || '')}</a> &rsaquo;
      <span>${escapeHtml(p.name)}</span>
    </nav>
    <div class="product-page-grid">
      <div class="product-page-visual">
        <img src="../${imgFor(p)}" alt="${escapeHtml(p.name)}" loading="lazy" width="800" height="800">
      </div>
      <div class="product-page-body">
        <p class="eyebrow">${escapeHtml(cat?.title || '')}</p>
        <h1>${escapeHtml(p.name)}</h1>
        <p class="lead">${escapeHtml(p.longDesc)}</p>
        <div class="cta-row">
          <a class="button" target="_blank" rel="sponsored noopener" href="${buyUrl}">Check price on Amazon</a>
          <a class="button light" target="_blank" rel="sponsored noopener" href="${revUrl}">Read Amazon reviews</a>
        </div>
        <p class="disclosure-mini">As an Amazon Associate I earn from qualifying purchases.</p>
      </div>
    </div>

    <section class="prose narrow">
      <h2>Why this can be a smart pick</h2>
      <ul>${p.why.map(w => `<li>${escapeHtml(w)}</li>`).join('')}</ul>

      <h2>What to check before you buy</h2>
      <ul>${p.watchOut.map(w => `<li>${escapeHtml(w)}</li>`).join('')}</ul>

      <h2>Great for</h2>
      <ul>${p.useCases.map(w => `<li>${escapeHtml(w)}</li>`).join('')}</ul>

      ${p.faqs?.length ? `<h2>Frequently asked questions</h2>
      <div class="faq">
        ${p.faqs.map(f => `<details><summary>${escapeHtml(f.q)}</summary><p>${escapeHtml(f.a)}</p></details>`).join('')}
      </div>` : ''}

      <div class="cta-row cta-row-wide">
        <a class="button" target="_blank" rel="sponsored noopener" href="${buyUrl}">Compare on Amazon</a>
      </div>
    </section>

    ${related.length ? `<section class="related">
      <h2>You might also like</h2>
      <div class="gadget-grid">
        ${related.map(r => `<article class="gadget-card">
          <div class="gadget-image" style="background-image:url('../assets/${encodeURI(r.image)}')"></div>
          <div class="gadget-content">
            <h3><a href="${r.slug}.html">${escapeHtml(r.name)}</a></h3>
            <p>${escapeHtml(r.shortDesc)}</p>
            <a class="button" href="${r.slug}.html">See buying guide &rarr;</a>
          </div>
        </article>`).join('')}
      </div>
    </section>` : ''}
  </div>
</main>
<div data-site-footer></div>
</body>
</html>
`;
}

for(const p of products){
  writeFileSync(join(root, `p/${p.slug}.html`), productPage(p));
}

// ---------- 3. Sitemap --------------------------------------------------
const urls = [
  '/',
  '/products.html',
  '/about.html',
  '/disclosure.html',
  '/privacy.html',
  '/guides.html',
  '/best-kitchen-gadgets-under-30.html',
  '/small-kitchen-essentials.html',
  '/best-kitchen-gifts.html',
  '/best-meal-prep-gadgets.html',
  '/family-kitchen-essentials.html',
  ...products.map(p => `/p/${p.slug}.html`)
];
const today = new Date().toISOString().slice(0,10);
const sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.map(u => `  <url><loc>${SITE_URL}${u}</loc><lastmod>${today}</lastmod><changefreq>weekly</changefreq><priority>${u === '/' ? '1.0' : '0.7'}</priority></url>`).join('\n')}
</urlset>
`;
writeFileSync(join(root, 'sitemap.xml'), sitemap);

console.log(`Built ${products.length} product pages, refreshed sitemap and browser data.`);
